package com.yeyamo_mobile.api.auth_service.event;

import java.util.UUID;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import com.fasterxml.jackson.databind.*;import com.yeyamo_mobile.api.auth_service.enums.Roles;import com.yeyamo_mobile.api.auth_service.models.*;import com.yeyamo_mobile.api.auth_service.repository.*;
@Component public class PartnerApprovedConsumer{private final ObjectMapper mapper;private final UserRepository users;private final RoleRepository roles;private final AuthProcessedEventRepository processed;private final AuthEventOutbox outbox;public PartnerApprovedConsumer(ObjectMapper m,UserRepository u,RoleRepository r,AuthProcessedEventRepository p,AuthEventOutbox o){mapper=m;users=u;roles=r;processed=p;outbox=o;}@KafkaListener(topics="${yeyamo.kafka.topics.partner-events:partner-events}",groupId="${spring.kafka.consumer.group-id:auth-service}")@Transactional public void consume(String raw)throws Exception{JsonNode e=mapper.readTree(raw);if(!"partner.approved".equals(text(e,"eventType")))return;UUID eventId=UUID.fromString(required(e,"eventId"));if(processed.existsById(eventId))return;JsonNode payload=e.path("payload");long userId=Long.parseLong(required(payload,"ownerUserId"));User user=users.findById(userId).orElseThrow(()->new IllegalStateException("Partner owner does not exist in auth-service"));Role role=roles.findByCode(Roles.PARTNER).orElseThrow(()->new IllegalStateException("PARTNER role is not seeded"));boolean changed=user.getRoles().add(role);if(changed){users.save(user);outbox.roleAdded(user,Roles.PARTNER.name(),text(e,"correlationId"));}processed.save(new AuthProcessedEvent(eventId,"partner.approved"));}private String required(JsonNode n,String f){String v=text(n,f);if(v==null||v.isBlank())throw new IllegalArgumentException(f+" is required");return v;}private String text(JsonNode n,String f){JsonNode v=n.get(f);return v==null||v.isNull()?null:v.asText();}}
